<script>
import { markRaw } from 'vue'
import { t } from '../../i18n.js'
import AppButton from '../../controls/AppButton.vue'
import AppSelect from '../../controls/AppSelect.vue'
import AppTextField from '../../controls/AppTextField.vue'
import AppMenu from '../../controls/AppMenu.vue'
import AppMenuItem from '../../controls/AppMenuItem.vue'
import AppSplitter from '../../controls/AppSplitter.vue'
import WorkspaceTabs from '../../controls/WorkspaceTabs.vue'
import FileWorkspaceTree from './FileWorkspaceTree.vue'
import FileWorkspaceInspector from './FileWorkspaceInspector.vue'
import FileWorkspaceLog from './FileWorkspaceLog.vue'
import FileWorkspaceDepots from './FileWorkspaceDepots.vue'
import FileWorkspaceStorage from './FileWorkspaceStorage.vue'
import { copyText } from '../../controls/clipboard.js'
import { prettySize } from '../checkin/files.js'
import { logEvent, redact } from '../debug/debugLog.js'

const views=[{id:'files',title:'Files',icon:'file'},{id:'pending',title:'Pending',icon:'clock'},{id:'submitted',title:'Submitted',icon:'check'},{id:'shelved',title:'Shelved',icon:'archive'},{id:'history',title:'History',icon:'history'},{id:'tasks',title:'Transfers',icon:'cloud-upload'},{id:'workspaces',title:'Workspaces',icon:'desktop'},{id:'streams',title:'Streams',icon:'workflow'},{id:'stream_graph',title:'Stream Graph',icon:'account-tree'},{id:'storage',title:'Storage administration',icon:'database',admin:true}]
views.splice(7,0,{id:'depots',title:'Depots',icon:'database'})
export default {
  components:{AppButton,AppSelect,AppTextField,AppMenu,AppMenuItem,AppSplitter,WorkspaceTabs,FileWorkspaceTree,FileWorkspaceInspector,FileWorkspaceLog,FileWorkspaceDepots,FileWorkspaceStorage},
  props:{ticket:String,project:String,login:String,canAdminister:Boolean},emits:['help','ready','debug'],
  data(){return {busy:false,error:'',disposed:false,generation:0,aborter:null,administrator:false,repositories:[],filesService:false,depotSelection:null,depotDraft:null,depotOriginal:null,storageDraft:null,storageOriginal:null,indexing:false,poll:null,tabs:views.slice(0,3),activeTabId:'pending',width:280,streams:[],tree:[],heads:{},stream:'',prefix:'',rows:[],after:null,children:{},expanded:[],focus:null,scope:'',shelved:false,storage:null,edges:[],operationLog:[],sequence:0}},
  computed:{viewPresets(){return views.filter(view=>!view.admin||this.administrator)},changeView(){return ['pending','submitted','shelved'].includes(this.activeTabId)},
    changeTree(){return this.rows.flatMap(row=>[{...row,id:row.code,kind:'change',depth:0,expanded:this.expanded.includes(row.code)},...(this.expanded.includes(row.code)?(this.children[row.code]?.items||[]).map(file=>({...file,name:file.path,id:row.code+'/'+file.path,kind:'file',depth:1,parent:row.code,stream:row.stream})):[]),...(this.expanded.includes(row.code)&&this.children[row.code]?.after?[{id:row.code+'/more',kind:'more',name:'Load more',depth:1,parent:row.code}]:[])])}},
  mounted(){
    try{const saved=JSON.parse(localStorage.getItem(this.settingsKey()));if(saved){this.tabs=(saved.tabs||this.tabs).filter(tab=>views.some(view=>view.id===tab.id));this.activeTabId=saved.activeTabId||'pending';this.width=Math.min(600,Math.max(220,saved.width||280));this.stream=saved.stream||'';this.prefix=saved.prefix||''}}catch{}
    this.poll=setInterval(()=>{if(this.activeTabId==='storage'&&!this.busy&&['queued','running'].includes(this.storage?.gc?.state))this.storageAction('storage_status')},2000)
    this.run(async signal=>{const {items:[capabilities,depots,streams]}=await this.command('read_batch',{requests:[{action:'capabilities',values:{}},{action:'depots',values:{limit:200}},{action:'streams',values:{limit:200}}]},signal);signal.throwIfAborted();this.administrator=capabilities.administrator;this.repositories=capabilities.repositories||[];this.filesService=capabilities.files_service_configured;this.tabs=this.tabs.filter(tab=>!tab.admin||this.administrator);if(!this.tabs.some(tab=>tab.id===this.activeTabId))this.activeTabId=this.tabs[0]?.id||'';
      signal.throwIfAborted();this.streams=streams.items;this.stream=this.streams.some(row=>row.code===this.stream)?this.stream:this.streams[0]?.code||'';
      this.tree=depots.items.flatMap(depot=>[{id:'depot/'+depot.code,kind:'depot',name:depot.code,depth:0,expanded:true},...this.streams.filter(row=>row.depot===depot.code).map(row=>({id:'stream/'+row.code,kind:'stream',name:row.code,stream:row.code,directory:'',depth:1,expanded:false}))]);await this.load(signal);this.$emit('ready')})
  },
  beforeUnmount(){this.disposed=true;this.indexing=false;clearInterval(this.poll);this.generation++;this.aborter?.abort()},
  methods:{t,prettySize,
    settingsKey(){return `file-inspection/${this.login}/${this.project}`},remember(){localStorage.setItem(this.settingsKey(),JSON.stringify({tabs:this.tabs,activeTabId:this.activeTabId,width:this.width,stream:this.stream,prefix:this.prefix}))},
    dirty(){return JSON.stringify(this.depotDraft)!==JSON.stringify(this.depotOriginal)||Boolean(this.storageDraft&&JSON.stringify(this.storageDraft.policy)!==JSON.stringify(this.storageOriginal))},
    canLeave(){if(this.dirty()){this.error=t('Save or reset Depot and Storage changes before leaving this project.');return false}return !this.busy},
    async command(action,values={},signal){const response=await fetch('/file-project/command?'+new URLSearchParams({project:this.project}),{method:'POST',signal,headers:{'Content-Type':'application/json','X-Tactic-Ticket':this.ticket},body:JSON.stringify({action,...values})});const body=await response.json();if(!response.ok){const error=new Error(body.error||response.statusText);error.file_error=body.file_error;throw error}return body},
    async run(work){this.aborter?.abort();this.aborter=markRaw(new AbortController());const generation=++this.generation;this.busy=true;this.error='';try{await work(this.aborter.signal)}catch(error){if(generation===this.generation&&error.name!=='AbortError'){this.error=t(redact(error.message));this.operationLog.push({id:++this.sequence,time:new Date().toLocaleTimeString(),level:'ERROR',operation:t('File operation'),message:this.error,path:redact(error.file_error?.path||'')});this.operationLog=this.operationLog.slice(-1000);logEvent({level:'ERROR',group:'file/inspection',message:this.error,details:error.file_error})}}finally{if(generation===this.generation&&!this.disposed){this.busy=false;this.remember()}}},
    async load(signal,more=false){const options={limit:200,after:more?this.after||'':''};let result;
      if(this.changeView)result=await this.command('changes',{...options,state:this.activeTabId,scope:this.administrator?'all':'mine'},signal);
      else if(this.activeTabId==='files')result=this.stream?await this.command('list',{...options,stream:this.stream,prefix:this.prefix},signal):{items:[]};
      else if(this.activeTabId==='history')result=this.focus?await this.command('history',{stream:this.focus.stream,path:this.focus.source_path||this.focus.path,limit:200},signal):{items:[]};
      else if(this.activeTabId==='tasks')result=await this.command('transfer_tasks',options,signal);
      else if(this.activeTabId==='storage'){const storage=await this.command('storage_status',{},signal);signal.throwIfAborted();this.acceptStorage(storage);result={items:[]}}
      else if(['depots','workspaces','streams','stream_graph'].includes(this.activeTabId))result=await this.command(this.activeTabId,options,signal);
      else result={items:[]};signal.throwIfAborted();if(this.activeTabId==='depots')this.depotSelection=null;this.rows=result.items;this.after=result.after||null;this.edges=result.edges||[];this.children={};this.expanded=[]},
    refresh(){return this.run(signal=>this.load(signal))},async openView(view){if(!view||this.busy)return;if(!this.tabs.some(tab=>tab.id===view.id))this.tabs.push(view);this.activeTabId=view.id;await this.refresh()},async closeTab(id){if(this.busy)return;this.tabs=this.tabs.filter(tab=>tab.id!==id);if(this.activeTabId===id){this.activeTabId=this.tabs[0]?.id||'';await this.refresh()}this.remember()},
    expand(node){if(node.kind==='depot')return;return this.run(async signal=>{const index=this.tree.findIndex(row=>row.id===node.id);let end=index+1;while(end<this.tree.length&&this.tree[end].depth>node.depth)end++;if(node.expanded){this.tree.splice(index+1,end-index-1);node.expanded=false;return}
      const page=await this.command('browse',{stream:node.stream,directory:node.directory,after:node.kind==='more'?node.after:'',published_change:this.heads[node.stream],limit:200},signal);signal.throwIfAborted();this.heads[node.stream]=page.published_change;
      const children=page.items.map(row=>({...row,id:'path/'+node.stream+'/'+row.path,depth:node.depth+(node.kind==='more'?0:1),stream:node.stream,directory:row.kind==='directory'?row.path:'',expanded:false}));if(page.after)children.push({id:node.id+'/more',kind:'more',name:'Load more',depth:node.depth+(node.kind==='more'?0:1),stream:node.stream,directory:node.directory,after:page.after});
      if(node.kind==='more')this.tree.splice(index,1,...children);else this.tree.splice(index+1,end-index-1,...children);node.expanded=true;
      if(this.tree.length>2000){this.tree.splice(2,this.tree.length-2000);this.operationLog.push({id:++this.sequence,time:new Date().toLocaleTimeString(),level:'INFO',operation:t('File operation'),message:t('Earlier tree rows released; reopen a folder to reload them.')})}})},
    selectDepot(node){if(node.kind==='more')return this.expand(node);if(node.kind==='file'){this.focus=node;this.scope='';this.shelved=false}else if(['directory','stream'].includes(node.kind)){this.stream=node.stream;this.prefix=node.directory;if(this.activeTabId==='files')this.refresh()}},
    expandChange(node){if(node.kind==='file'){this.focus=node;this.scope=node.parent;this.shelved=this.activeTabId==='shelved';return}if(node.kind==='change'&&this.expanded.includes(node.code)){this.expanded=this.expanded.filter(code=>code!==node.code);delete this.children[node.code];return}const code=node.parent||node.code,row=this.rows.find(row=>row.code===code);return this.run(async signal=>{const page=await this.command('inspect_change_files',{[row.state==='shelved'?'shelf':'change']:code,limit:200,after:node.kind==='more'?this.children[code].after:''},signal);signal.throwIfAborted();this.children[code]=page;if(!this.expanded.includes(code))this.expanded.push(code)})},
    selectFile(row){this.focus={...row,stream:this.stream};this.scope='';this.shelved=false},
    selectDepotRecord(row){this.depotSelection=row},
    editDepot(row){if(this.depotDraft&&JSON.stringify(this.depotDraft)!==JSON.stringify(this.depotOriginal)){this.error=t('Save or reset the current depot draft first.');return}return this.run(async signal=>{const info=row?await this.command('depot_status',{depot:row.code},signal):{};signal.throwIfAborted();this.depotDraft={creating:!row,code:info.code||'',title:info.title||'',repository:info.storage?.repository||'',revision:info.revision||0};this.depotOriginal=({...this.depotDraft})})},
    resetDepot(){this.depotDraft=({...this.depotOriginal});this.error=''},
    cancelDepot(){if(JSON.stringify(this.depotDraft)!==JSON.stringify(this.depotOriginal)){this.error=t('Save or reset the current depot draft first.');return}this.depotDraft=null;this.depotOriginal=null},
    saveDepot(){const draft=this.depotDraft;return this.run(async signal=>{const values={title:draft.title,repository:draft.repository||null,...(draft.creating?{code:draft.code.trim()}:{depot:draft.code,revision:draft.revision})};const result=await this.command(draft.creating?'create_depot':'update_depot',values,signal);signal.throwIfAborted();this.depotDraft=null;this.depotOriginal=null;await this.load(signal);signal.throwIfAborted();this.depotSelection=result})},
    acceptStorage(status){const pristine=!this.storageDraft||JSON.stringify(this.storageDraft.policy)===JSON.stringify(this.storageOriginal);this.storage=status;if(pristine&&status.policy_values)this.resetPolicy()},
    resetPolicy(){this.storageOriginal=this.storage?.policy_values?{...this.storage.policy_values}:null;this.storageDraft=this.storage?.policy_values?{revision:this.storage.policy_revision,policy:{...this.storage.policy_values}}:null;this.error=''},
    savePolicy(){return this.run(async signal=>{for(const [key,value] of Object.entries(this.storageDraft.policy)){if(!/^[0-9]{1,19}$/.test(value)||BigInt(value)>9223372036854775807n||(key==='max_parallel'&&(BigInt(value)<1n||BigInt(value)>16n)))throw new Error(t('Enter non-negative whole numbers; parallel transfers must be from 1 to 16.'))}await this.command('storage_policy',{revision:this.storageDraft.revision,policy:this.storageDraft.policy},signal);this.acceptStorage(await this.command('storage_status',{},signal));signal.throwIfAborted();this.resetPolicy()})},
    storageAction(operation,dry_run){if(this.busy)return;if(operation==='gc_begin'&&dry_run===false&&!window.confirm(t('Run safe GC using the configured retention policy?')))return;return this.run(async signal=>{this.indexing=operation==='storage_index';try{const values=operation==='gc_begin'?{dry_run}:operation==='gc_cancel'?{task:this.storage.gc.code}:{};await this.command(operation,values,signal);signal.throwIfAborted();this.acceptStorage(await this.command('storage_status',{},signal));while(this.indexing&&!this.storage.indexed){await this.command('storage_index',{},signal);signal.throwIfAborted();this.acceptStorage(await this.command('storage_status',{},signal))}}finally{this.indexing=false}})},
    async copyLog(){await copyText(this.operationLog.map(row=>[row.time,row.message,row.path].filter(Boolean).join(' · ')).join('\n'))},async copyPath(){if(this.focus)await copyText('//'+this.focus.stream+'/'+(this.focus.source_path||this.focus.path))},
  },
}
</script>
<template>
  <section class="file-workspace" :aria-busy="busy" :aria-label="t('File project inspection')">
    <header class="inspection-toolbar"><AppMenu label="View" show-label overlay><AppMenuItem v-for="view in viewPresets" :key="view.id" :label="view.title" :icon="view.icon" @click="openView(view)" /></AppMenu><AppButton label="Refresh" icon="refresh" :disabled="busy" @click="refresh" /><span class="muted">{{ t('Use TACTIC Handler for checkout, local changes and Submit.') }}</span><AppButton label="Help" icon="help" @click="$emit('help','file_workspace')" /></header>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <div class="inspection-body"><nav :style="{width:width+'px'}"><FileWorkspaceTree :nodes="tree" :busy="busy" :can-drag="false" label="Depot tree" @expand="expand" @select="selectDepot" /></nav><AppSplitter v-model="width" label="Depots" :min="220" :max="600" />
      <main><WorkspaceTabs kind="view" :tabs="tabs" :selected="activeTabId" @select="openView(viewPresets.find(view=>view.id===$event))" @close="closeTab" @reorder="tabs=$event;remember()" /><p v-if="!tabs.length" class="muted">{{ t('Open a view from the View menu') }}</p>
        <FileWorkspaceTree v-if="changeView" :nodes="changeTree" :busy="busy" :can-drag="false" label="Changelist tree" @expand="expandChange" @select="expandChange" />
        <FileWorkspaceDepots v-else-if="activeTabId==='depots'" :rows="rows" :after="after" :selected="depotSelection" :draft="depotDraft" :repositories="repositories" :administrator="administrator" :busy="busy" @refresh="refresh" @more="run(signal=>load(signal,true))" @select="selectDepotRecord" @edit="editDepot" @change="depotDraft=$event" @save="saveDepot" @reset="resetDepot" @cancel="cancelDepot" />
        <FileWorkspaceStorage v-else-if="activeTabId==='storage'&&storage" :status="storage" :draft="storageDraft" :busy="busy" :indexing="indexing" :files-service="filesService" @change="storageDraft=$event" @save="savePolicy" @reset="resetPolicy" @action="storageAction" @stop="indexing=false" />
        <template v-else><div v-if="activeTabId==='files'" class="inspection-filter"><AppSelect v-model="stream" label="Streams" :options="streams.map(row=>({value:row.code,label:row.code}))" :translate-labels="false" @update:model-value="refresh" /><AppTextField v-model="prefix" label="Path prefix" @keydown.enter="refresh" /><AppButton label="Filter" icon="filter" @click="refresh" /></div>
          <div class="inspection-scroll"><table><thead><tr><th>{{ t(activeTabId==='files'?'File':activeTabId==='history'?'Revision':'Details') }}</th><th>{{ t('State') }}</th><th>{{ t('File size') }}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.path||row.code||row.task||index" tabindex="0" :aria-selected="focus?.path===row.path" @click="activeTabId==='files'&&selectFile(row)" @keydown.enter="activeTabId==='files'&&selectFile(row)"><td>{{ row.path||row.code||row.task||'#'+row.number }}</td><td>{{ row.state||row.stream||row.action||'—' }}</td><td>{{ prettySize(row.size||row.bytes_total||0) }}</td></tr></tbody></table><pre v-if="['workspaces','streams','stream_graph'].includes(activeTabId)">{{ JSON.stringify(rows,null,2) }}</pre><pre v-if="activeTabId==='stream_graph'">{{ JSON.stringify(edges,null,2) }}</pre></div>
        </template>
        <footer v-if="!['depots','storage'].includes(activeTabId)"><AppButton v-if="after" label="Next page" icon="next" :disabled="busy" @click="run(signal=>load(signal,true))" /><AppButton label="Copy depot path" icon="copy" :disabled="!focus" @click="copyPath" /></footer><FileWorkspaceInspector v-if="!['depots','storage'].includes(activeTabId)" :call="command" :row="focus" :stream="stream" :scope="scope" :shelved="shelved" workspace="" />
      </main>
    </div><FileWorkspaceLog :entries="operationLog" @clear="operationLog=[]" @copy="copyLog" @debug="$emit('debug')" />
  </section>
</template>
<style scoped>
.file-workspace{display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;gap:6px}.inspection-toolbar,.inspection-filter,footer{display:flex;flex-wrap:wrap;align-items:center;gap:6px;flex:none}.inspection-toolbar>span{flex:1;min-width:160px;font-size:var(--text-caption)}.inspection-body{display:flex;flex:1;min-height:0;min-width:0}.inspection-body>nav{display:flex;flex-direction:column;min-width:0;flex:none}main{display:flex;flex-direction:column;flex:1;min-width:0;min-height:0}.inspection-scroll{flex:1;min-height:0;overflow:auto;scrollbar-gutter:stable;padding:4px 12px 4px 4px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:5px;overflow-wrap:anywhere}tr[aria-selected=true]{background:var(--selected)}tr:focus-visible{outline:2px solid var(--primary)}pre{white-space:pre-wrap;overflow-wrap:anywhere}form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px}@media(max-width:700px){.inspection-body>nav{max-width:35%}.inspection-toolbar>span{width:100%}}
</style>
